/**
 * [FS-WECHAT-SAMEONE-DEF] 同一个人被拆成两行时先并掉（跨群同一个备注算同一个人）。
 *
 * 微信侧同一个人的 id 有两种写法：真实的 `wxid_xxx`，和早期群消息里带的纯数字 id。
 * 两种写法分别在两个群先露过面时，会各建一行 person（备注名相同、canonical 不同），
 * 结果「同一个菲菲」在两个群各有一份记忆、好感也各算一份。
 *
 * 判据（两条全中才并，宁可漏并也不错并）：
 *  1) 备注名完全相等 —— 主人在同一个人身上的两个群备注是同一串；
 *  2) 两个 id 形态不同（一个 wxid_ 开头、一个纯数字）—— 同一个人的两种写法。
 * 并法：本次 id 登记到既有那行（两个 id 都指向同一个 canonical，wxid 是其中主键之一），
 * 备注名与另一个 id 一起进 aliases；不删行、不动已有记忆。
 *
 * @returns {string|null} 并过去之后的 canonical_id；没并返回 null
 */
export function mergeWechatSameNameRows(db, wechatId, nickname, nowMs = Date.now()) {
	const id = String(wechatId ?? '').trim();
	const name = String(nickname ?? '').trim();
	if (id === '' || name === '') return null;
	// 已经认得出的（登记过映射）不用猜；但备注名还得记进别名——主人在群里按备注叫人，
	// 别名里没有这串备注就等于白认，人物的记忆也就串不起来。
	const known = canonicalOfWechat(db, id);
	if (known !== null) {
		if (known !== 'master') {
			let aliases = [];
			try {
				const row = db.prepare('SELECT aliases FROM person WHERE canonical_id = ?').get(known);
				aliases = Array.isArray(row?.aliases) ? row.aliases : (row?.aliases ? JSON.parse(String(row.aliases)) : []);
			} catch { aliases = []; }
			if (!aliases.includes(name)) {
				aliases.push(name);
				db.prepare('UPDATE person SET aliases = ? WHERE canonical_id = ?').run(JSON.stringify(aliases), known);
			}
		}
		return null;
	}
	const idIsWxid = /^wxid_/i.test(id);
	const cands = db.prepare(`
		SELECT p.canonical_id AS cid, p.aliases AS aliases, a.wechat_id AS wechat_id
		  FROM person p
		  JOIN person_wechat_alias a ON a.canonical_id = p.canonical_id
		 WHERE p.display_name = ? AND p.deleted_at IS NULL AND p.canonical_id <> 'master'
	`).all(name);
	for (const cand of cands) {
		const other = String(cand.wechat_id ?? '').trim();
		if (other === '' || other === id) continue;
		// 同形态（都是 wxid / 都是数字）= 另一串 id，不是同一个人的两种写法
		if (/^wxid_/i.test(other) === idIsWxid) continue;
		const cid = String(cand.cid);
		setWechatAlias(db, id, cid);
		let aliases = [];
		try { aliases = Array.isArray(cand.aliases) ? cand.aliases : (cand.aliases ? JSON.parse(String(cand.aliases)) : []); } catch { aliases = []; }
		for (const extra of [name, other]) if (extra !== '' && !aliases.includes(extra)) aliases.push(extra);
		db.prepare('UPDATE person SET aliases = ?, last_seen_at = MAX(last_seen_at, ?) WHERE canonical_id = ?')
			.run(JSON.stringify(aliases), nowMs, cid);
		return cid;
	}
	return null;
}

